static int skip[10][10],vis[10];static int dfs(int cur,int left){if(left==0)return 1;vis[cur]=1;int r=0;for(int nxt=1;nxt<=9;nxt++)if(!vis[nxt]&&(skip[cur][nxt]==0||vis[skip[cur][nxt]]))r+=dfs(nxt,left-1);vis[cur]=0;return r;}int numberOfPatterns(int m,int n){int p[][3]={{1,3,2},{1,7,4},{3,9,6},{7,9,8},{1,9,5},{3,7,5},{4,6,5},{2,8,5}};for(int i=0;i<8;i++){skip[p[i][0]][p[i][1]]=p[i][2];skip[p[i][1]][p[i][0]]=p[i][2];}int r=0;for(int len=m;len<=n;len++)r+=dfs(1,len-1)*4+dfs(2,len-1)*4+dfs(5,len-1);return r;}
